def is_valid_currency_amount(s):
    if len(s) < 2 or s[0] != '$':
        return False
    i = 1
    n = len(s)
    group_lengths = []
    current = 0
    while i < n and s[i].isdigit():
        current += 1
        i += 1
        if i < n and s[i] == ',':
            group_lengths.append(current)
            current = 0
            i += 1
    group_lengths.append(current)
    if group_lengths[0] < 1 or group_lengths[0] > 3:
        return False
    for g in group_lengths[1:]:
        if g != 3:
            return False
    if i == n:
        return True
    if s[i] != '.':
        return False
    frac = s[i+1:]
    return len(frac) == 2 and frac.isdigit()

