def is_balanced_ignoring_whitespace(s):
    chars = [c for c in s if not c.isspace()]
    allowed = set('()[]{}')
    if any(c not in allowed for c in chars):
        return False
    closers = {')': '(', ']': '[', '}': '{'}
    stack = []
    for c in chars:
        if c in closers.values():
            stack.append(c)
        else:
            if not stack or stack[-1] != closers[c]:
                return False
            stack.pop()
    return not stack

